import gzip, math, itertools

def open_text(p):
    f=open(p,'rb'); m=f.read(2); f.close()
    return gzip.open(p,'rt') if m==b'\\x1f\\x8b' else open(p)

def load_cols(p):
    cols=[[] for _ in range(8)]
    with open_text(p) as h:
        h.readline()
        for line in h:
            fs=line.rstrip('\\n').split('\\t')
            for i,x in enumerate(fs[1:9]): cols[i].append(math.log1p(float(x)))
    return cols

def pearson(x,y):
    mx=sum(x)/len(x); my=sum(y)/len(y)
    num=sum((a-mx)*(b-my) for a,b in zip(x,y))
    vx=sum((a-mx)**2 for a in x); vy=sum((b-my)**2 for b in y)
    return num/(vx*vy)**0.5

def corrmat(cols): return [[pearson(cols[i],cols[j]) for j in range(8)] for i in range(8)]
R=corrmat(load_cols('inputs/multiome.match.atac.rna.q1.rna.tsv.gz'))
A=corrmat(load_cols('inputs/multiome.match.atac.rna.q1.atac.tsv.gz'))
# find perm p mapping RNA i -> ATAC p[i], compare R[i,k] to A[p[i],p[k]] offdiag
best=None; second=None
for p in itertools.permutations(range(8)):
    err=0; corrx=[]; corry=[]
    for i in range(8):
        for k in range(i+1,8):
            corrx.append(R[i][k]); corry.append(A[p[i]][p[k]])
            err+=(R[i][k]-A[p[i]][p[k]])**2
    score=-err
    if best is None or score>best[0]: second=best; best=(score,p,corrx,corry)
    elif second is None or score>second[0]: second=(score,p,corrx,corry)
print('best',best[1],best[0], 'second',second[1],second[0], 'margin',best[0]-second[0], 'corr-of-corr',pearson(best[2], best[3]))
for row in R: print('R', ['%.3f'%x for x in row])
print('A perm matrix')
p=best[1]
for i in range(8): print('A', ['%.3f'%A[p[i]][p[j]] for j in range(8)])
PY"

