# quick local diagnostic: compare TSS, gene body, and body+promoter bin aggregation assignments
import gzip, re, math, itertools

def open_text(p):
    f=open(p,'rb'); m=f.read(2); f.close(); return gzip.open(p,'rt') if m==b'\\x1f\\x8b' else open(p)
def table(p):
    names=[]; vals=[]
    with open_text(p) as h:
        h.readline()
        for l in h:
            fs=l.rstrip('\\n').split('\\t'); names.append(fs[0]); vals.append([float(x) for x in fs[1:9]])
    return names, vals
def attrs(s): return dict(re.findall(r'([A-Za-z0-9_]+) \"(["'^"]*)"'"', s))
genes={}; priority={'protein_coding':0,'lncRNA':1,'processed_transcript':2}
with open_text('reference/gencode.v44.annotation.gtf.gz') as h:
    for l in h:
        if not l or l[0]=='#': continue
        f=l.rstrip('\\n').split('\\t')
        if len(f)<9 or f[2]"'!='"'gene': continue
        a=attrs(f[8]); n=a.get('gene_name'); typ=a.get('gene_type','')
        if not n: continue
        rec=(priority.get(typ,9), f[0], int(f[3])-1, int(f[4]), f[6], typ)
        if n not in genes or rec[0]<genes[n][0]: genes[n]=rec
rn,rv=table('inputs/multiome.match.atac.rna.q1.rna.tsv.gz')
bn,bv=table('inputs/multiome.match.atac.rna.q1.atac.tsv.gz')
atac={}
for n,v in zip(bn,bv):
    try:
        c,s,e=n.rsplit('_',2); atac[(c,int(s))]=v
    except: pass

def pear(x,y):
    n=len(x); mx=sum(x)/n; my=sum(y)/n
    num=sum((a-mx)*(b-my) for a,b in zip(x,y)); vx=sum((a-mx)**2 for a in x); vy=sum((b-my)**2 for b in y)
    return num/(vx*vy)**0.5 if vx and vy else float('nan')
def rank(v):
    o=sorted(range(len(v)), key=v.__getitem__); r=[0]*len(v); i=0
    while i<len(o):
        j=i+1
        while j<len(o) and v[o[j]]==v[o[i]]: j+=1
        rr=(i+j-1)/2+1
        for k in range(i,j): r[o[k]]=rr
        i=j
    return r
def corrmat(rm,am,spearman=False):
    rc=[[math.log1p(row[i]) for row in rm] for i in range(8)]
    ac=[[math.log1p(row[i]) for row in am] for i in range(8)]
    if spearman: rc=[rank(c) for c in rc]; ac=[rank(c) for c in ac]
    return [[pear(rc[i], ac[j]) for j in range(8)] for i in range(8)]
def best(M):
    b=s=None
    for p in itertools.permutations(range(8)):
        sc=sum(M[i][p[i]] for i in range(8))
        if b is None or sc>b[0]: s=b; b=(sc,p)
        elif s is None or sc>s[0]: s=(sc,p)
    return b,s

def collect(mode, flank=0):
    rm=[]; am=[]; missing=0; nobin=0
    for n,r in zip(rn,rv):
        g=genes.get(n)
        if not g: missing+=1; continue
        _,chrom,start0,end,strand,typ=g
        if mode=='tss':
            t=start0 if strand"'!='"'-' else end-1; starts=[(t//10000)*10000 + off for off in range(-flank,flank+1,10000)]
        elif mode=='body':
            bs=(start0//10000)*10000; be=((end-1)//10000)*10000; starts=list(range(bs,be+1,10000))
        elif mode=='body_prom':
            t=start0 if strand"'!='"'-' else end-1; bs=(min(start0,t-flank)//10000)*10000; be=((max(end-1,t+flank))//10000)*10000; starts=list(range(bs,be+1,10000))
        bins=[atac[(chrom,s)] for s in starts if (chrom,s) in atac]
        if not bins: nobin+=1; continue
        # try sum not mean, because longer genes may legitimately collect more accessibility
        agg=[sum(b[i] for b in bins) for i in range(8)]
        rm.append(r); am.append(agg)
    return rm,am,missing,nobin
for mode,flank in [('tss',0),('tss',50000),('body',0),('body_prom',50000),('body_prom',100000)]:
    rm,am,mis,no=collect(mode,flank)
    for sp in [False,True]:
        M=corrmat(rm,am,sp); b,s=best(M)
        print(mode,flank,'spear' if sp else 'pear','n',len(rm),'assign',';'.join(map(str,b[1])),'score',round(b[0],6),'margin',round(b[0]-s[0],6),'minrow',round(min(max(r) for r in M),6))
PY"

